// Service worker for production — offline-first strategy with versioned cache.
//
// This file replaces service-worker.js at publish time.
// It uses the auto-generated service-worker-assets.js manifest (created by the
// .NET SDK's <ServiceWorkerAssetsManifest> MSBuild property) to pre-cache all
// static assets (WASM binaries, DLLs, CSS, JS, images) with integrity hashes.
//
// Strategy:
// 1. On install: pre-cache all assets listed in the manifest
// 2. On fetch: serve from cache first, fall back to network
// 3. On activate: delete old caches from previous versions

// Import the asset manifest generated by dotnet publish.
// This file contains an array of { url, hash } objects for every static asset.
self.importScripts('./service-worker-assets.js');

// Cache name includes a unique hash so each publish creates a fresh cache.
// When new assets are deployed, the old cache is automatically cleaned up.
self.addEventListener('install', event => event.waitUntil(onInstall(event)));
self.addEventListener('activate', event => event.waitUntil(onActivate(event)));
self.addEventListener('fetch', event => event.respondWith(onFetch(event)));

const cacheNamePrefix = 'offline-cache-';
const cacheName = `${cacheNamePrefix}${self.assetsManifest.version}`;

// List of URL prefixes that should NEVER be cached.
// API calls must always go to the network to get fresh data.
const offlineAssetsExclude = [
    /^\/api\//,          // Backend API calls — always fresh
    /\/swagger/,         // Swagger UI (dev only)
    /hot-reload/,        // .NET hot reload (dev only)
    /_blazor\/negotiate/  // SignalR negotiation (not used in WASM, but safety)
];

// List of additional assets to cache that aren't in the manifest.
// External CDN resources used by the app (fonts, Quill editor).
const offlineAssetsInclude = [
    /\.dll$/,
    /\.pdb$/,
    /\.wasm/,
    /\.html/,
    /\.js$/,
    /\.json$/,
    /\.css$/,
    /\.woff$/,
    /\.png$/,
    /\.jpe?g$/,
    /\.gif$/,
    /\.ico$/,
    /\.blat$/,
    /\.dat$/
];

/// <summary>
/// Pre-caches all static assets from the manifest during service worker installation.
/// Each asset is stored with its integrity hash for cache-busting.
/// </summary>
async function onInstall(event) {
    console.info('[PWA] Service worker installing...');

    // Filter the asset manifest to only cache relevant file types
    const assetsRequests = self.assetsManifest.assets
        .filter(asset => offlineAssetsInclude.some(pattern => pattern.test(asset.url)))
        .map(asset => new Request(asset.url, { integrity: asset.hash, cache: 'no-cache' }));

    // Open the versioned cache and store all filtered assets
    const cache = await caches.open(cacheName);
    await cache.addAll(assetsRequests);

    console.info(`[PWA] Cached ${assetsRequests.length} assets.`);
}

/// <summary>
/// Cleans up old caches from previous versions when a new service worker activates.
/// Only caches with our prefix are deleted — other caches are left untouched.
/// </summary>
async function onActivate(event) {
    console.info('[PWA] Service worker activating...');

    // Delete all caches that match our prefix but aren't the current version
    const cacheKeys = await caches.keys();
    await Promise.all(
        cacheKeys
            .filter(key => key.startsWith(cacheNamePrefix) && key !== cacheName)
            .map(key => caches.delete(key))
    );

    console.info('[PWA] Old caches cleaned up.');
}

/// <summary>
/// Intercepts all fetch requests and serves from cache first (offline-first strategy).
/// If the request is not in cache, falls back to network.
/// API calls and excluded patterns always go directly to the network.
/// </summary>
async function onFetch(event) {
    // Only handle GET requests — POST/PUT/DELETE always go to network
    if (event.request.method !== 'GET') {
        return fetch(event.request);
    }

    // Check if this URL should be excluded from caching (API calls, etc.)
    const requestUrl = new URL(event.request.url);
    const shouldExclude = offlineAssetsExclude.some(pattern => pattern.test(requestUrl.pathname));

    if (shouldExclude) {
        return fetch(event.request);
    }

    // Cache-first strategy: try cache, then fall back to network
    const cache = await caches.open(cacheName);
    const cachedResponse = await cache.match(event.request);

    if (cachedResponse) {
        return cachedResponse;
    }

    // Not in cache — fetch from network
    return fetch(event.request);
}
